"use client";

import React, { useState, useEffect } from "react";
import { motion, AnimatePresence, type Transition } from "motion/react";
import { X, Sparkles, Compass } from "lucide-react";
import { cn } from "@/lib/utils";

export interface AppStoreCardItem {
  id: string;
  category: string;
  title: string;
  subtitle: string;
  description: string;
  image: string;
  theme?: "light" | "dark";
}

const DEFAULT_CARDS: AppStoreCardItem[] = [
  {
    id: "trip-apps",
    category: "Travel",
    title: "5 Inspiring Apps for Your Next Global Trip",
    subtitle: "Curated collection",
    description:
      "Love to travel? So do the makers of these five subscription apps. Discover hidden alleys, navigate high-speed trains, and translate menus seamlessly in real time.",
    image: "https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80",
    theme: "dark",
  },
  {
    id: "mindful-flow",
    category: "Wellness",
    title: "Daily Meditations & Spatial Soundscapes",
    subtitle: "App of the Day",
    description:
      "Transform your workspace routine with binaural beats, ambient forest audio, and scientifically backed breathing timers tailored to your heart rate variability.",
    image: "https://images.unsplash.com/photo-1511497584788-87676104235f?auto=format&fit=crop&w=800&q=80",
    theme: "dark",
  },
];

const springTransition: Transition = {
  type: "spring",
  stiffness: 350,
  damping: 30,
};

export function AppStoreCardGrid({
  cards = DEFAULT_CARDS,
  className,
}: {
  cards?: AppStoreCardItem[];
  className?: string;
}) {
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const selectedCard = cards.find((c) => c.id === selectedId);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") setSelectedId(null);
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, []);

  return (
    <div
      data-slot="app-store-card"
      className={cn("w-full max-w-4xl mx-auto p-4 select-none", className)}
    >
      {/* Header */}
      <div className="flex items-center justify-between mb-6 px-2">
        <div>
          <span className="text-xs font-bold uppercase tracking-wider text-neutral-400 font-mono">
            Today
          </span>
          <h2 className="text-2xl font-black tracking-tight text-neutral-900 dark:text-neutral-100">
            Featured Stories
          </h2>
        </div>
        <div className="flex h-9 w-9 items-center justify-center rounded-full bg-neutral-100 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-300">
          <Sparkles className="h-4 w-4 text-amber-500" />
        </div>
      </div>

      {/* Grid of Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
        {cards.map((card) => (
          <motion.div
            key={card.id}
            layoutId={`card-container-${card.id}`}
            onClick={() => setSelectedId(card.id)}
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
            transition={springTransition}
            className="relative h-96 overflow-hidden rounded-3xl cursor-pointer shadow-xl border border-white/20 dark:border-white/10"
          >
            {/* Background Image */}
            <motion.div
              layoutId={`card-image-${card.id}`}
              className="absolute inset-0 h-full w-full"
            >
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={card.image}
                alt={card.title}
                className="h-full w-full object-cover"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/30 to-transparent" />
            </motion.div>

            {/* Card Content Overlay */}
            <motion.div
              layoutId={`card-content-${card.id}`}
              className="relative z-10 flex h-full flex-col justify-end p-6 text-white"
            >
              <span className="text-xs font-bold uppercase tracking-wider text-white/70 font-mono">
                {card.category}
              </span>
              <h3 className="text-xl font-bold tracking-tight mt-1 leading-snug">
                {card.title}
              </h3>
              <p className="text-xs text-white/80 mt-2 line-clamp-2">
                {card.subtitle}
              </p>
            </motion.div>
          </motion.div>
        ))}
      </div>

      {/* Expanded Modal View */}
      <AnimatePresence>
        {selectedCard ? (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-8">
            {/* Backdrop */}
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setSelectedId(null)}
              className="absolute inset-0 bg-black/60 backdrop-blur-md"
            />

            {/* Expanded Modal Card */}
            <motion.div
              layoutId={`card-container-${selectedCard.id}`}
              transition={springTransition}
              className="relative z-10 w-full max-w-lg overflow-hidden rounded-3xl bg-white dark:bg-neutral-900 shadow-2xl max-h-[85vh] overflow-y-auto"
            >
              {/* Hero Image Container */}
              <div className="relative h-72 w-full">
                <motion.div
                  layoutId={`card-image-${selectedCard.id}`}
                  className="absolute inset-0 h-full w-full"
                >
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <img
                    src={selectedCard.image}
                    alt={selectedCard.title}
                    className="h-full w-full object-cover"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent" />
                </motion.div>

                {/* Close Button */}
                <button
                  type="button"
                  onClick={() => setSelectedId(null)}
                  className="absolute top-4 right-4 z-20 flex h-9 w-9 items-center justify-center rounded-full bg-black/50 text-white backdrop-blur-md transition-transform hover:scale-110 active:scale-95 cursor-pointer"
                >
                  <X className="h-4 w-4" />
                </button>

                {/* Header text on hero */}
                <motion.div
                  layoutId={`card-content-${selectedCard.id}`}
                  className="absolute bottom-6 left-6 right-6 z-10 text-white"
                >
                  <span className="text-xs font-bold uppercase tracking-wider text-white/70 font-mono">
                    {selectedCard.category}
                  </span>
                  <h3 className="text-2xl font-black tracking-tight mt-1 leading-snug">
                    {selectedCard.title}
                  </h3>
                </motion.div>
              </div>

              {/* Full Article Content */}
              <motion.div
                initial={{ opacity: 0, y: 15 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: 15 }}
                transition={{ delay: 0.1, duration: 0.2 }}
                className="p-6 space-y-4"
              >
                <div className="flex items-center gap-3 p-3 rounded-2xl bg-neutral-100 dark:bg-neutral-800">
                  <Compass className="h-5 w-5 text-pink-500" />
                  <div>
                    <p className="text-xs font-bold text-neutral-900 dark:text-neutral-100">
                      Editor&apos;s Recommendation
                    </p>
                    <p className="text-[11px] text-neutral-500">
                      Handpicked for design excellence
                    </p>
                  </div>
                </div>

                <p className="text-sm text-neutral-700 dark:text-neutral-300 leading-relaxed">
                  {selectedCard.description}
                </p>

                <button
                  type="button"
                  onClick={() => setSelectedId(null)}
                  className="w-full py-3 rounded-2xl bg-pink-500 text-white font-bold text-xs uppercase tracking-wider shadow-lg hover:bg-pink-600 transition-all active:scale-98 cursor-pointer mt-2"
                >
                  Get All Featured Apps
                </button>
              </motion.div>
            </motion.div>
          </div>
        ) : null}
      </AnimatePresence>
    </div>
  );
}
